const form=document.querySelector('#login-form'),email=document.querySelector('#email'),password=document.querySelector('#password'),error=document.querySelector('#login-error'),submit=form.querySelector('[type=submit]');
document.querySelectorAll('[data-demo]').forEach(button=>button.addEventListener('click',()=>{email.value=button.dataset.demo+'@demo.sikepo.tech';password.value='SikepoDemo!2026';document.querySelectorAll('[data-demo]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));error.hidden=true;submit.focus();}));
document.querySelector('#toggle-password').addEventListener('click',event=>{const visible=password.type==='password';password.type=visible?'text':'password';event.target.textContent=visible?'Sembunyikan':'Tampilkan';event.target.setAttribute('aria-pressed',String(visible));});
form.addEventListener('submit',async event=>{event.preventDefault();error.hidden=true;submit.disabled=true;submit.querySelector('strong').textContent='Memeriksa akun…';try{const response=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:email.value.trim(),password:password.value}),credentials:'same-origin'});if(!response.headers.get('content-type')?.includes('application/json'))throw new Error('Server sedang memulai ulang. Coba lagi sebentar.');const result=await response.json();if(!response.ok)throw new Error(result.error||'Login belum berhasil.');location.assign(result.redirect);}catch(err){error.textContent=err.message==='Failed to fetch'?'Server belum dapat dihubungi. Coba lagi nanti.':err.message;error.hidden=false;}finally{submit.disabled=false;submit.querySelector('strong').textContent='Masuk ke dashboard';}});
